import { executeChild, proxyActivities, workflowInfo } from "@temporalio/workflow";

const { runAttempt } = proxyActivities({ startToCloseTimeout: "10 minutes", retry: { maximumAttempts: 1 } });

export async function buildAttempt({ key, branch, attempt }) {
  return runAttempt({ key, branch, attempt });
}

export async function attempts({ key, n }) {
  const ids = Array.from({ length: n }, (_, i) => `a${i + 1}`);
  const results = await Promise.allSettled(ids.map((attempt) =>
    executeChild(buildAttempt, {
      workflowId: `${workflowInfo().workflowId}:${attempt}`,
      args: [{ key, branch: `nova/${key}-${attempt}`, attempt }],
    })));
  const finished = results.filter((r) => r.status === "fulfilled").map((r) => r.value);
  const survivors = finished.filter((a) => a.lockedChecksPass && a.verifyPass);
  const failed = results.filter((r) => r.status === "rejected").length;
  if (survivors.length === 0) return { winner: null, failed, dropped: finished.map((a) => a.attempt) };
  const winner = survivors[0];
  return { winner: winner.attempt, branch: winner.branch, failed, dropped: finished.filter((a) => a !== winner).map((a) => a.attempt) };
}

