// Stands in for one attempt on its own full VM: build from the approved plan, then run the checks.
import { sleep } from "@temporalio/activity";

const OUTCOMES = {
  a1: { lockedChecksPass: true, verifyPass: false, changedLines: 64, note: "QA checks pass, but it broke a neighbouring test" },
  a2: { lockedChecksPass: true, verifyPass: true, changedLines: 41, note: "all checks pass" },
  a3: "the VM died twice",
};

export async function runAttempt({ key, branch, attempt }) {
  await sleep(1000 + Math.random() * 1000); // the real thing takes an hour
  const outcome = OUTCOMES[attempt];
  if (typeof outcome === "string") throw new Error(`${attempt}: ${outcome}`);
  console.log(`${key} ${attempt} on ${branch}: ${outcome.note}`);
  return { attempt, branch, ...outcome };
}
EOF

